SELECT *, CUME_DIST() OVER (PARTITION BY product_id ORDER BY quantity DESC NULLS FIRST) quantity_cume_dist, MIN(quantity) OVER (PARTITION BY store_id) store_id_min_quantity, LAG(quantity, 2) OVER (ORDER BY last_restock, id) prev_quantity, SUM(quantity) OVER (PARTITION BY store_id ORDER BY quantity, id ROWS BETWEEN UNBOUNDED PRECEDING AND CURRENT ROW) cumulative_quantity, SUM(quantity) OVER (ORDER BY quantity, id ROWS BETWEEN UNBOUNDED PRECEDING AND CURRENT ROW) running_quantity FROM inventory
